INSERT  IGNORE INTO `examen_preguntas` VALUES (1,'Son derechos político-electorales de la ciudadanía mexicana:','Votar, ser votada y prestar voluntariamente servicios o funciones oficiales a un gobierno extranjero, sin permiso del Ejecutivo Federal.','Poder ser votada en condiciones de paridad para todos los cargos de elección popular, teniendo las calidades que establezca la ley; poder ser nombrado para cualquier empleo o comisión del servicio público, teniendo las calidades que establezca la ley y votar en las consultas populares. ','Asociarse individual y libremente para tomar parte en forma pacífica en los asuntos políticos del país; votar y formar parte de los cuerpos de reserva en términos de ley.','NINGUNA','B',NULL,NULL,NULL),(2,'Es el medio de identificación necesario para poder votar:','Credencial para Votar','Pasaporte vigente','Licencia de conducir','NINGUNA','A',NULL,NULL,NULL),(3,'Ley máxima que rige la vida económica, social y política en México y que determina el estatus social de ciudadanía mexicana:','Constitución Política de los Estados Unidos Mexicanos','Ley General de Instituciones y Procedimientos Electorales','Constitución Política del Estado Libre y Soberano de Chiapas','NINGUNA','A',NULL,NULL,NULL),(4,'Los derechos o prerrogativas de la ciudadanía mexicana pueden suspenderse por:','Religión, preferencia política, condición económica y estado de salud.','Por tener sentencia firme por la comisión intencional de delitos de violencia familiar, violencia familiar equiparada o doméstica, violación a la intimidad sexual; por violencia política contra las mujeres en razón de género.','Por causa de migración.','NINGUNA','B',NULL,NULL,NULL),(5,'Señala una razón por la que se suspenden los derechos o prerrogativas ciudadanas','Por vagancia o ebriedad consuetudinaria, declarada en los términos que prevengan las leyes','Desempeñar los cargos concejiles del municipio donde resida, las funciones electorales y las de jurado','Ninguna persona mexicana por nacimiento podrá ser privada de su nacionalidad','NINGUNA','A',NULL,NULL,NULL),(6,'Temas que no pueden ser sometidos a consulta popular, según la Constitución Política de los Estados Unidos Mexicanos:','Sobre la restricción de los derechos humanos  ','Temas que repercuten en la mayor parte del territorio nacional','Temas de trascendencia que repercutan en una o varias entidades federativas','NINGUNA','A',NULL,NULL,NULL),(7,'De acuerdo con la Constitución Política de los Estados Unidos Mexicanos, la participación de la ciudadanía en las consultas populares es: ','Una condición','Un derecho y una obligación ','Una suspensión de derechos','NINGUNA','B',NULL,NULL,NULL),(8,'La nacionalidad mexicana por naturalización se pierde por: ','Usar un pasaporte extranjero','Residir durante 3 años continuos en el extranjero','Ninguna de las anteriores','NINGUNA','A',NULL,NULL,NULL),(9,'El artículo 35, fracción IX de la Constitución Política de los Estados Unidos Mexicanos determina el derecho de la ciudadanía a participar en los procesos de revocación de mandato, mismos que deberán ser convocados por el siguiente organismo:','Poder Legislativo','Presidencia de la República','Instituto Nacional Electoral','NINGUNA','C',NULL,NULL,NULL),(10,'El artículo 34 de la Constitución Política de los Estados Unidos Mexicanos, establece que, tener la calidad de mexicanos, un modo honesto de vivir y haber cumplido 18 años son ___________________ para considerar la ciudadanía mexicana.','Derechos ','Requisitos','Obligaciones ','NINGUNA','B',NULL,NULL,NULL),(11,'¿Cuál es la diferencia entre nacionalidad y ciudadanía?','La ciudadanía es la pertenencia a una ciudad y la nacionalidad es la pertenencia a una nación.','No existe diferencia.','La nacionalidad es la pertenencia a una nación, y la ciudadanía es la participación que puede tener esa persona en la vida del estado, después de reunir los requisitos exigidos por la Ley para ser considerada ciudadana.','NINGUNA','C',NULL,NULL,NULL),(12,'Son obligaciones de la ciudadanía mexicana:','Votar en las elecciones, las consultas populares y los procesos de revocación de mandato, en los términos que señale la ley.','Votar en las elecciones federales y locales, por la persona candidata que determine la autoridad local o federal. ','Poder ser votada en condiciones de paridad para todos los cargos de elección popular, teniendo las calidades que establezca la ley.','NINGUNA','A',NULL,NULL,NULL),(13,'La credencial para votar con fotografía, tiene las siguientes utilidades:','Como medio de identificación y como garantía de apoyos por parte de los partidos políticos. ','Para votar por candidaturas a puestos de elección popular y como medio de identificación. ','Para votar por candidaturas a puestos de elección popular y como identificación para poder viajar al extranjero. ','NINGUNA','B',NULL,NULL,NULL),(14,'Es el mecanismo de participación ciudadana por el cual las y los ciudadanos ejercen su derecho a expresar su opinión respecto de uno o varios temas de trascendencia Estatal, a través del voto emitido.','Iniciativa popular','Plebiscito ','Consulta popular ','NINGUNA','C',NULL,NULL,NULL),(15,'Son tres de los instrumentos de participación ciudadana que señala Ley de Participación Ciudadana del Estado de Chiapas','Iniciativa popular, recuento de votos y plebiscito','Audiencia pública, referéndum y reelección ','Plebiscito, iniciativa popular y consulta popular.','NINGUNA','C',NULL,NULL,NULL),(16,'En México, la edad para obtener la ciudadanía es:','21 años','18 años','25 años','NINGUNA','B',NULL,NULL,NULL),(17,'La __________________ es una vía de participación de la ciudadanía en los procesos electorales.','Observación electoral.','Resolución de medios de impugnación. ','Integración de tribunales electorales locales. ','NINGUNA','A',NULL,NULL,NULL),(18,'Señala una atribución del Poder Ejecutivo establecida en la Constitución Política de los Estados Unidos Mexicanos:','Aprobar los tratados internacionales y convenciones diplomáticas','Resolver las impugnaciones en las elecciones federales de diputados y senadores','Promulgar y ejecutar las leyes que expida el Congreso de la Unión, proveyendo en la esfera administrativa a su exacta observancia','NINGUNA','C',NULL,NULL,NULL),(19,'Señala una atribución del Congreso de la Unión establecida en la Constitución Política de los Estados Unidos Mexicanos:','Legislar en toda la República sobre hidrocarburos, minería, sustancias químicas, explosivos, pirotecnia, industria cinematográfica, comercio, juegos con apuestas y sorteos, intermediación y servicios financieros, energía eléctrica y nuclear y para expedir las leyes del trabajo.','Dirimir los conflictos que se susciten entre los estados y la federación en materia de límites territoriales.','Resolver impugnaciones en las elecciones. ','NINGUNA','A',NULL,NULL,NULL),(20,'El Poder ___________________ se deposita en una Suprema Corte de Justicia, en un Tribunal Electoral, en Plenos Regionales, en Tribunales Colegiados de Circuito, en Tribunales Colegiados de Apelación y en Juzgados de Distrito.','Ejecutivo','Legislativo','Judicial','NINGUNA','C',NULL,NULL,NULL),(21,'La Cámara de Diputados del Congreso de la Unión está conformada por:','300 diputaciones de mayoría relativa, 200 de representación proporcional','200 diputaciones de mayoría relativa y 100 de representación proporcional','100 diputaciones de mayoría relativa y 100 de representación proporcional','NINGUNA','A',NULL,NULL,NULL),(22,'Cada 6 años se llevan a cabo elecciones federales en las cuales la ciudadanía elige a la persona titular de la Presidencia de la República, identifica al tipo de democracia al que se hace referencia:','Social','Representativa','Económica','NINGUNA','B',NULL,NULL,NULL),(23,'Es un órgano de gobierno que se integra por 1 presidencia municipal, 1 sindicatura y 3, 5 o 6 regidurías, conforme a los criterios establecidos en la Ley de Instituciones y Procedimientos Electorales del Estado de Chiapas, de conformidad con el principio de paridad de género.','Ayuntamiento','Gubernatura','Diputación Local','NINGUNA','A',NULL,NULL,NULL),(24,'La base de la organización política y administrativa del Estado de Chiapas, de conformidad con el artículo 115 de la Constitución Política de los Estados Unidos Mexicanos es:','El municipio ','Tribunal de Justicia Administrativa','Distritos electorales locales','NINGUNA','A',NULL,NULL,NULL),(25,'En las elecciones locales del Estado de Chiapas podrán participar los ________________ de carácter nacional y con registro local, así como la ciudadanía con candidaturas independientes.','Organizaciones ciudadanas','Instituciones electorales','Partidos políticos','NINGUNA','C',NULL,NULL,NULL),(26,'El Congreso del Estado de Chiapas se integra por:','24 diputaciones de mayoría relativa y 16 de representación proporcional','40 diputaciones de mayoría relativa y 16 de representación proporcional','16 diputaciones de mayoría relativa y 40 de representación proporcional','NINGUNA','A',NULL,NULL,NULL),(27,'Es el responsable de impulsar la equidad de género en la integración de la Administración Pública Estatal, por lo que no podrá nombrar a más del cincuenta por cierto de personas de un mismo género como titulares de las Dependencias de la Administración Pública del Estado.','Titular del Poder Ejecutivo','Presidencia del Congreso del estado','Titular del Tribunal Superior de Justicia','NINGUNA','A',NULL,NULL,NULL),(28,'Para el ejercicio de sus atribuciones, el ____________ se deposita en el Tribunal Superior de Justicia, Consejo de la Judicatura, y Tribunal Administrativo.','Poder Judicial del Estado de Chiapas','Congreso del Estado de Chiapas','Ayuntamientos del Estado de Chiapas','NINGUNA','A',NULL,NULL,NULL),(29,'Es una característica de la forma de gobierno del Estado de Chiapas:','Democrática','Transparente','Federalizada','NINGUNA','A',NULL,NULL,NULL),(30,'Es un derecho político de la ciudadanía chiapaneca establecida en la Constitución Política del Estado de Chiapas:','Desarrollar actividades académicas y científicas.','Poder ser votada en condiciones de paridad para todos los cargos de elección popular, teniendo las calidades que establezca la ley.','Representar al Estado de Chiapas en exposiciones turísticas nacionales.','NINGUNA','B',NULL,NULL,NULL),(31,'El Congreso del Estado de Chiapas se elige en su totalidad con diputadas y diputados electos cada:','3 años','6 años','2 años','NINGUNA','A',NULL,NULL,NULL),(32,'La ciudadanía chiapaneca tiene derecho a acceder a los siguientes cargos de representación popular a nivel estatal:','Gubernatura del Estado, Diputaciones del Congreso del Estado, Ayuntamientos','Secretaría de Estado, Comités vecinales y representaciones partidistas','Representantes de asociaciones civiles, organizaciones no gubernamentales y organismos privados','NINGUNA','A',NULL,NULL,NULL),(33,'Son las autoridades administrativas electorales encargadas de organizar los procesos electorales federales y locales.','Instituto Nacional Electoral y Organismos Públicos Locales Electorales.','Tribunal Electoral del Poder Judicial de la Federación y Tribunales Electorales Locales.','Fiscalía Especializada en materia de Delitos Electorales y Tribunal Electoral del Estado de Chiapas.','NINGUNA','A',NULL,NULL,NULL),(34,'Se encarga de organizar las elecciones federales, es decir, la elección de la presidencia de la República, diputaciones y senadurías que integran el Congreso de la Unión.','Instituto de Elecciones y Participación Ciudadana','Tribunal Electoral del Poder Judicial de la Federación','Instituto Nacional Electoral','NINGUNA','C',NULL,NULL,NULL),(35,'Es uno de los fines del Instituto Nacional Electoral:','Garantizar la celebración periódica y pacífica de las elecciones para renovar a las personas integrantes de los Poderes Legislativo y Ejecutivo de la Unión','Organizar las elecciones locales para renovar a los integrantes del Congreso del Estado, al Gobernador y a los Miembros de Ayuntamientos','Tiene por objeto el desarrollo eficiente de la radiodifusión y las telecomunicaciones','NINGUNA','A',NULL,NULL,NULL),(36,'Es la autoridad administrativa electoral encargada de la ubicación de las casillas y la designación del funcionariado de sus mesas directivas.','Instituto de Elecciones y Participación Ciudadana','Instituto Nacional Electoral','Tribunal Electoral del Estado de Chiapas','NINGUNA','B',NULL,NULL,NULL),(37,'¿Cuántas Juntas Distritales Ejecutivas integran al Instituto Nacional Electoral?','32, una por cada entidad federativa.','300, una por cada distrito electoral.','125, una por cada municipio de Chiapas.','NINGUNA','B',NULL,NULL,NULL),(38,'Se encargan de instalar la casilla, recibir la votación, realizar el escrutinio y cómputo de la votación, clausurar la casilla e informar de los resultados.','Juntas Locales Ejecutivas','Consejos distritales y municipales','Integrantes de mesas directivas de casillas','NINGUNA','C',NULL,NULL,NULL),(39,'En las entidades federativas, las elecciones locales y, en su caso, las consultas populares y los procesos de revocación de mandato están a cargo de:','Tribunales Electorales Locales','Organismos Públicos Locales Electorales','Fiscalía Especializada en materia de Delitos Electorales','NINGUNA','B',NULL,NULL,NULL),(40,'¿Cómo se integra el órgano superior de dirección (Consejo General) de los Organismos Públicos Locales Electorales?','Por una consejera o un consejero presidente y cuatro consejeras y consejeros electorales, con derecho a voz y voto; la secretaria o el secretario ejecutivo solo con derecho a voz.','Por una consejera o un consejero presidente y seis consejeras y consejeros electorales, con derecho a voz y voto; la secretaria o el secretario ejecutivo y representantes de los partidos políticos con registro nacional o estatal, quienes concurrirán a las sesiones solo con derecho a voz.','Por una consejera o un consejero presidente y siete consejeras y consejeros electorales, con derecho a voz y voto; dos secretarias o secretarios ejecutivos y representantes de los partidos políticos con registro nacional o estatal, quienes concurrirán a las sesiones solo con derecho a voz.','NINGUNA','B',NULL,NULL,NULL),(41,'Se encarga de organizar las elecciones locales para renovar a los integrantes del Congreso del Estado, al Gobernador y a los Miembros de Ayuntamientos en el estado de Chiapas.','Instituto Nacional Electoral','Tribunal Electoral del Estado de Chiapas','Instituto de Elecciones y Participación Ciudadana','NINGUNA','C',NULL,NULL,NULL),(42,'Es una de las funciones del Instituto de Elecciones y Participación Ciudadana en Chiapas.','Organizar las elecciones locales para renovar a las personas integrantes del Congreso del Estado, a la Gubernatura y a miembros de ayuntamientos en el estado de Chiapas.','Organizar las elecciones federales, es decir, la elección de la presidencia de la República, diputaciones y senadurías que integran el Congreso de la Unión.','Determinar la ubicación de casillas y la designación del funcionariado de sus mesas directivas.','NINGUNA','A',NULL,NULL,NULL),(43,'Es la autoridad jurisdiccional especializada en materia electoral en el Estado de Chiapas.','Tribunal Electoral del Estado de Chiapas','Tribunal Electoral del Poder Judicial de la Federación','Instituto de Elecciones y Participación Ciudadana','NINGUNA','A',NULL,NULL,NULL),(44,'Se encarga de investigar y perseguir los delitos electorales establecidos en la Ley General en materia de Delitos Electorales.','Tribunal Electoral del Estado de Chiapas','Fiscalía Especializada en Materia de Delitos Electorales','Instituto Nacional Electoral','NINGUNA','B',NULL,NULL,NULL),(45,'En Chiapas, es un órgano permanente que se encarga de prevenir, investigar y perseguir los delitos en materia electoral y los que guardan relación con todas y cada una de las etapas del proceso electoral, adscrito a la Fiscalía General del Estado.','Instituto de Elecciones y Participación Ciudadana','Fiscalía de Delitos Electorales del Estado de Chiapas','Tribunal Electoral del Estado de Chiapas.','NINGUNA','B',NULL,NULL,NULL),(46,'Son principios de la función electoral.','Certeza, legalidad, independencia, imparcialidad, máxima publicidad, objetividad, paridad, y se realizarán con perspectiva de género.','Solidaridad, igualdad y transparencia.','Respeto, tolerancia y compasión.','NINGUNA','A',NULL,NULL,NULL),(47,'¿Cuáles son las autoridades electorales locales en Chiapas?','El Instituto Nacional Electoral, Tribunal Electoral del Poder Judicial de la Federación y la Fiscalía Especializada en materia de Delitos Electorales.','Secretaría General de Gobierno, Instituto de Capacitación y Vinculación Tecnológica del Estado de Chiapas y el Instituto de Protección Social y Beneficencia Pública del Estado de Chiapas.','El Instituto de Elecciones y Participación Ciudadana, el Tribunal Electoral del Estado de Chiapas y la Fiscalía de Delitos Electorales del Estado de Chiapas.','NINGUNA','C',NULL,NULL,NULL),(48,'Son órganos que funcionan durante los procesos electorales locales:','Juntas Locales y Juntas Distritales Ejecutivas','Consejos Distritales y Municipales','Casillas Básicas, Contiguas, Extraordinarias y Especiales  ','NINGUNA','B',NULL,NULL,NULL),(49,'Es uno de los requisitos para ser consejera o consejero electoral:','Estar inscrita/o en el Padrón Electoral','Haber residido durante los últimos dos años en el Estado','Ser ciudadana/o chiapaneco, en pleno ejercicio de sus derechos civiles y políticos','NINGUNA','C',NULL,NULL,NULL),(50,'Además de una presidencia y una representación de cada partido político con registro y en su caso de candidaturas independientes ¿Quiénes más integran los consejos distritales y municipales?','Una secretaría técnica, 4 consejerías electorales propietarias y 3 suplentes comunes','Una secretaría técnica, 4 consejerías electorales propietarias y 4 suplentes generales','4 consejerías electorales propietarias, 3 suplentes y una secretaria técnica','NINGUNA','A',NULL,NULL,NULL),(51,'Las ausencias temporales o definitivas de algunas consejeras o consejeros electorales, son cubiertas por:','La o el presidente del consejo','Otra consejera u otro consejero electoral propietario','Las o los consejeros suplentes comunes','NINGUNA','C',NULL,NULL,NULL),(52,'Los Consejos Distritales y Municipales electorales, para su funcionamiento ¿cuándo deben instalarse? ','El primero de marzo','Dentro de los siguientes diez días de su integración','A más tardar el 15 de marzo del año de la elección','NINGUNA','B',NULL,NULL,NULL),(53,'Una vez instalados los consejos distritales y municipales sesionaran por menos ______al mes hasta la conclusión del proceso electoral:','Una vez','Dos veces ','Tres veces','NINGUNA','A',NULL,NULL,NULL),(54,'Convocar a sesiones ordinarias, extraordinarias y especiales a los integrantes del Consejo Distrital o Municipal electoral, es una atribución de ____________________.','La o el consejero electoral','La o el secretario técnico ','La o el presidente ','NINGUNA','C',NULL,NULL,NULL),(55,'Controlar y supervisar la administración de los recursos humanos, materiales y financieros del Consejo Distrital o Municipal electoral, es una atribución de___________________.','La o el consejero electoral','La o el secretario técnico ','La o el presidente ','NINGUNA','B',NULL,NULL,NULL),(56,'De acuerdo con la Ley de Instituciones y Procedimientos Electorales, los Consejos Distritales y Municipales electorales, funcionan durante los procesos electorales locales, residen en cada una de las cabeceras de distrito y municipios y se integran el día ___ del mes de marzo del año de la elección:','10','15','1°','NINGUNA','C',NULL,NULL,NULL),(57,'Una vez instalados sesionan por lo menos una vez al mes:','Los Consejos Distritales Electorales','Los Consejos Municipales Electorales','Ambos','NINGUNA','C',NULL,NULL,NULL),(58,'Las y los consejeros electorales propietarios del Instituto de Elecciones y Participación Ciudadana (IEPC) durarán en su cargo ________________ ordinario, pudiendo ser reelectos por otros dos:','Dos procesos electorales','Un proceso electoral','Tres procesos electorales','NINGUNA','B',NULL,NULL,NULL),(59,'Para que puedan sesionar los Consejos Distritales y Municipales electorales del Instituto de Elecciones y Participación Ciudadana (IEPC) se requiere la mayoría de sus integrantes, entre los que deberán, al menos:','La o el presidente, una o un consejero electoral y representaciones de partidos políticos ','La o el presidente, una o un consejero electoral y la o el secretario técnico','La o el presidente y dos consejeras o consejeros electorales','NINGUNA','C',NULL,NULL,NULL),(60,'En las sesiones de los consejos distritales y municipales electorales, toda resolución se tomará por: ','Mayoría de votos de las consejerías electorales','Mayoría de voto de las representaciones de partidos políticos','Mayoría de votos de todas y todos los que participan en la sesión','NINGUNA','A',NULL,NULL,NULL),(61,'Registrar concurrentemente con el Consejo General a las candidaturas a diputaciones de mayoría relativa y a miembros de los Ayuntamientos, es una atribución de:','Las o los presidentes de los Consejos Distritales y Municipales electorales','Las o los secretarios técnicos de los Consejos Distritales y municipales','Los Consejos Distritales y Municipales electorales  ','NINGUNA','C',NULL,NULL,NULL),(62,'Remitir a la Dirección Ejecutiva de Organización Electoral del Instituto de Elecciones y Participación Ciudadana (IEPC), la documentación relativa a sus sesiones y la de los respectivos procesos electorales, es una atribución de:','Las o los presidentes de los Consejos Distritales y Municipales electorales','Las o los secretarios técnicos de los Consejos Distritales y municipales','Los Consejos Distritales y Municipales electorales  ','NINGUNA','A',NULL,NULL,NULL),(63,'Son entidades de interés público con personalidad jurídica y patrimonio propios, con registro legal ante el INE o ante los Organismos Públicos Locales, y tienen como fin promover la participación del pueblo en la vida democrática, contribuir a la integración de los órganos de representación política y, como organizaciones de ciudadanos, hacer posible el acceso de éstos al ejercicio del poder público.','Partidos políticos','Agrupaciones políticas','Asociaciones políticas','NINGUNA','A',NULL,NULL,NULL),(64,'Una __________ es la alianza entre dos o más partidos políticos que unen fuerzas para presentar a las mismas candidaturas, con el fin de aumentar sus posibilidades de obtener el triunfo en una elección.','Unión','Coalición ','Asociación','NINGUNA','B',NULL,NULL,NULL),(65,'En México existen:','Partidos políticos federales','Partidos políticos nacionales y locales','Partidos políticos federales y estatales','NINGUNA','B',NULL,NULL,NULL),(66,'Los __________ son aquellos que cuentan con registro ante el INE','Partidos políticos locales','Partidos políticos nacionales y locales','Partidos políticos nacionales','NINGUNA','C',NULL,NULL,NULL),(67,'A los Organismos Públicos Locales les corresponde:','Registrar los partidos políticos locales','Registrar los partidos políticos nacionales','La fiscalización de los ingresos y egresos de los partidos','NINGUNA','A',NULL,NULL,NULL),(68,'Son los tipos de coaliciones que pueden formar los partidos políticos','Completas y parciales','Totales y blandas','Totales, parciales y flexibles','NINGUNA','C',NULL,NULL,NULL),(69,'Es un partido político local:','Partido Verde Ecologista de México','Partido Chiapas Unido','Partido Movimiento Ciudadano','NINGUNA','B',NULL,NULL,NULL),(70,'Se entiende como ____________, aquélla en la que los partidos políticos coaligados postulan en un mismo proceso federal o local, a la totalidad de sus candidatos a puestos de elección popular bajo una misma plataforma electoral.','Coalición total','Coalición parcial','Coalición flexible ','NINGUNA','A',NULL,NULL,NULL),(71,'¿Cuál de las siguientes siglas corresponde a las de un partido político nacional?','PES Chiapas','PMCH','PAN','NINGUNA','C',NULL,NULL,NULL),(72,'De entre las siguientes opciones, elige la que corresponda a un partido político local.','Partido de la Revolución Democrática','Partido Podemos Mover a Chiapas','MORENA','NINGUNA','B',NULL,NULL,NULL),(73,'Tienen el derecho de participar en elecciones federales para la presidencia de la República, senadurías y diputaciones, así como locales para la gubernatura, diputaciones y ayuntamientos.','Los partidos políticos','Las agrupaciones políticas','Las asociaciones políticas','NINGUNA','A',NULL,NULL,NULL),(74,'Es un partido político nacional','Partido Podemos Mover a Chiapas','Partido de la Revolución Democrática','Partido Chiapas Unido','NINGUNA','B',NULL,NULL,NULL),(75,'Es una de las causas de pérdida de registro de un partido político','No obtener por lo menos el 10% de la votación válida emitida','No obtener por lo menos el 5% de la votación válida emitida','No obtener por lo menos el 3% de la votación válida emitida ','NINGUNA','C',NULL,NULL,NULL),(76,'Los partidos políticos tienen representación en el Consejo General del Instituto de Elecciones y Participación Ciudadana (IEPC) con:','Voz y voto','Sin voz ni voto','Únicamente con voz','NINGUNA','C',NULL,NULL,NULL),(77,'Es un partido político nacional ','Partido del Trabajo','Partido Chiapas Unido','Podemos Mover a Chiapas','NINGUNA','A',NULL,NULL,NULL),(78,'Constituyen dos fines del Instituto de Elecciones y Participación Ciudadana (IEPC)','Promover el voto y garantizar la celebración periódica, auténtica y pacífica de las elecciones para renovar a las y los integrantes del poder legislativo y a la persona titular del poder ejecutivo en Chiapas.','Informar y sensibilizar a la ciudadanía sobre los delitos establecidos en la Ley General en Materia de Delitos Electorales.','Garantizar que todos los actos y resoluciones electorales locales y procedimientos de participación ciudadana, se sujeten al principio de constitucionalidad, convencionalidad y lega